202	    /**
203	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
204	     * single space, then the national digits grouped in threes from the left (e.g. the stored
205	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
206	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
207	     * digit string.
208	     *
209	     * @return the human-readable telephone, or the stored value when it cannot be formatted
210	     */
211	    public String getTelephoneDisplay() {
212	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
213	            return this.telephone;
214	        }
215	        String digits = this.telephone.substring(1);
216	        String countryCode = extractCountryCode(digits);
217	        String national = digits.substring(countryCode.length());
218	        StringBuilder display = new StringBuilder("+").append(countryCode);
219	        for (int i = 0; i < national.length(); i += 3) {
220	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
221	        }
222	        return display.toString();
