235	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
236	            String code = entry.getKey();
237	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
238	                return code;
239	            }
240	        }
241	        return digits.substring(0, 1);
