324	     * @return the fiscal year, or {@code null} when the registration date is absent
325	     */
326	    public String getFiscalYear() {
327	        if (this.registrationDate == null) {
328	            return null;
329	        }
330	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
