333	    /**
334	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
335	     * is named by the calendar year in which it ends: a date in July through December belongs to the
336	     * next calendar year's fiscal year, while January through June stays in the current one.
337	     *
338	     * @param date the date to classify
339	     * @return the fiscal year as a four-digit calendar year
340	     */
341	    private static int fiscalYearOf(LocalDate date) {
342	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
343	    }
344	
345	    /**
346	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
347	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
348	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
349	     *
350	     * @return the Luhn check digit, or {@code null} when the customer code is absent
351	     */
352	    public Integer getCheckDigit() {
353	        if (this.customerCode == null) {
354	            return null;
355	        }
356	        int sum = 0;
357	        boolean dbl = true;
358	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
359	            char c = this.customerCode.charAt(i);
360	            if (c < '0' || c > '9') {
361	                continue;
362	            }
363	            int d = c - '0';
364	            if (dbl) {
365	                d *= 2;
366	                if (d > 9) {
367	                    d -= 9;
368	                }
369	            }
370	            sum += d;
371	            dbl = !dbl;
372	        }
373	        return (10 - (sum % 10)) % 10;
374	    }
375	
376	    /**
377	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
378	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
379	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
380	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
381	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
382	     * tenure, the tenure points are never awarded at create time.
383	     *
384	     * @return the membership points, a non-negative integer
385	     */
386	    public Integer getMembershipPoints() {
387	        int points = 0;
388	        boolean hasEmail = this.email != null && !this.email.isBlank();
389	        if (hasEmail) {
390	            points += 2;
391	        }
392	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
393	        if (hasNoNamesakes) {
394	            points += 1;
395	        }
396	        if (this.householdSize != null && this.householdSize >= 3) {
397	            points += 2;
398	        }
399	        Long tenureFiscalYears = getTenureFiscalYears();
400	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
401	            points += 3;
402	        }
403	        return points;
404	    }
405	
406	    /**
407	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
408	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
409	     * for 6 or more points.
410	     *
411	     * @return the membership level, an integer from 1 to 4
412	     */
413	    public Integer getMembershipLevel() {
414	        int points = getMembershipPoints();
415	        if (points <= 1) {
416	            return 1;
417	        }
418	        if (points <= 3) {
419	            return 2;
420	        }
421	        if (points <= 5) {
422	            return 3;
423	        }
424	        return 4;
425	    }
426	
427	    /**
428	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
429	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
430	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
431	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
432	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
433	     * yet.
434	     *
435	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
436	     */
437	    public Long getTenureFiscalYears() {
438	        if (this.registrationDate == null) {
439	            return null;
440	        }
441	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
442	    }
443	
444	    /**
445	     * The owner's locality, the canonical region string. Once the owner has a
446	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
447	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
448	     * source of truth. Before the customer code is assigned (for example while a create is still
449	     * validating the postcode) it falls back to the region the code will be built from: the
450	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
451	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
452	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
453	     *
454	     * @return the canonical region string, or {@code 'UNKNOWN'}
455	     */
456	    public String getLocality() {
457	        if (this.customerCode != null) {
458	            int dash = this.customerCode.indexOf('-');
459	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
460	        }
461	        return deriveRegion();
462	    }
463	
464	    /**
465	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
466	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
467	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
468	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
469	     *
470	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
471	     */
472	    public String getTimezone() {
473	        return REGION_TIMEZONE.get(getLocality());
474	    }
475	
476	    /**
477	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
478	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
479	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
480	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
481	     * the same region for known cities but disambiguates cities that share a name.
482	     *
483	     * @return the canonical region string, or {@code 'UNKNOWN'}
484	     */
485	    private String deriveRegion() {
486	        String region = regionFromPostcode();
487	        if (region != null) {
488	            return region;
489	        }
490	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
491	    }
492	
493	    /**
494	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
495	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
496	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
497	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
498	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
499	     * owner's region, telephone and last name. Call this once at create time and store the result via
500	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
501	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
502	     *
503	     * @return the assembled customer code
504	     */
505	    public String buildCustomerCode() {
506	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
507	    }
508	
509	    /**
510	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
511	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
512	     *
513	     * @param value the value to hash
514	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
515	     */
516	    private static String sha256Hex8(String value) {
517	        try {
518	            byte[] digest = MessageDigest.getInstance("SHA-256")
519	                .digest(value.getBytes(StandardCharsets.UTF_8));
520	            StringBuilder hex = new StringBuilder(8);
521	            for (int i = 0; i < 4; i++) {
522	                hex.append(String.format("%02X", digest[i]));
523	            }
524	            return hex.toString();
525	        }
526	        catch (NoSuchAlgorithmException e) {
527	            throw new IllegalStateException("SHA-256 algorithm not available", e);
528	        }
529	    }
530	
531	    /**
532	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
533	     * absent, not a 4-digit number, or in no known range.
534	     *
535	     * @return the matching region, or {@code null}
536	     */
537	    private String regionFromPostcode() {
538	        if (this.postcode == null) {
539	            return null;
540	        }
541	        int value;
542	        try {
543	            value = Integer.parseInt(this.postcode.trim());
544	        }
545	        catch (NumberFormatException ex) {
546	            return null;
547	        }
548	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
549	            int[] range = entry.getValue();
550	            if (value >= range[0] && value <= range[1]) {
551	                return entry.getKey();
552	            }
553	        }
554	        return null;
555	    }
556	
557	    /**
558	     * The owner's preferred contact channel, derived from the owner's details. Returns
559	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
560	     *
561	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
562	     */
563	    public String getContactPreference() {
564	        boolean hasEmail = this.email != null && !this.email.isBlank();
565	        return hasEmail ? "EMAIL" : "PHONE";
566	    }
567	
568	    /**
569	     * The owner's identity key, the single derived value used for duplicate detection. It is the
570	     * owner's normalized telephone, email (empty when absent) and household id joined with
571	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
572	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
573	     * are equal, so two members of the same household with different telephones differ here and are
574	     * both allowed.
575	     *
576	     * @return the derived identity key
577	     */
578	    public String getIdentityKey() {
579	        return (this.telephone == null ? "" : this.telephone) + "|"
580	            + (this.email == null ? "" : this.email) + "|"
581	            + (this.householdId == null ? "" : this.householdId);
582	    }
583	
584	    public String getHouseholdId() {
585	        return this.householdId;
586	    }
587	
588	    public void setHouseholdId(String householdId) {
589	        this.householdId = householdId;
590	    }
591	
592	    public Integer getNamesakeCount() {
593	        return this.namesakeCount;
594	    }
595	
596	    public void setNamesakeCount(Integer namesakeCount) {
597	        this.namesakeCount = namesakeCount;
598	    }
599	
600	    public Integer getHouseholdSize() {
601	        return this.householdSize;
602	    }
603	
604	    public void setHouseholdSize(Integer householdSize) {
605	        this.householdSize = householdSize;
606	    }
607	
608	    public String getPostcode() {
609	        return this.postcode;
610	    }
611	
612	    public void setPostcode(String postcode) {
613	        this.postcode = postcode;
614	    }
615	
616	    public Boolean getBulkSignupWarning() {
617	        return this.bulkSignupWarning;
618	    }
619	
620	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
621	        this.bulkSignupWarning = bulkSignupWarning;
622	    }
623	
624	    public Boolean getPossibleDuplicate() {
625	        return this.possibleDuplicate;
626	    }
627	
628	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
629	        this.possibleDuplicate = possibleDuplicate;
630	    }
631	
632	    public Integer getPossibleDuplicateOf() {
633	        return this.possibleDuplicateOf;
634	    }
635	
636	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
637	        this.possibleDuplicateOf = possibleDuplicateOf;
638	    }
639	
640	    /**
641	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
642	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
643	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
644	     *
645	     * @return whether the owner has been soft-deleted
646	     */
647	    public boolean isDeleted() {
648	        return this.deleted;
649	    }
650	
651	    public void setDeleted(boolean deleted) {
652	        this.deleted = deleted;
653	    }
654	
655	    /**
656	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
657	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
658	     */
659	    @PrePersist
660	    void onCreate() {
661	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
662	    }
663	
664	    /**
665	     * Resolves the effective registration date and rolls it onto a business day. An absent
666	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
667	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
668	     * holiday: starting from the effective date, the date advances one day at a time while it lands
669	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
670	     * non-holiday business day. A date already on a business day is returned unchanged.
671	     *
672	     * <p>This is the single definition of both the defaulting and the business-day roll, used
673	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
674	     * stamps the owner and by the create endpoint that counts owners per business day.
675	     *
676	     * @param supplied the registration date from the request, or {@code null} when none was supplied
677	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
678	     */
679	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
680	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
681	        while (!isBusinessDay(effective)) {
682	            effective = effective.plusDays(1);
683	        }
684	        return effective;
685	    }
686	
687	    /**
688	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
689	     */
690	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
691	        LocalDate.of(2026, 1, 1),
692	        LocalDate.of(2026, 1, 26),
693	        LocalDate.of(2026, 4, 25),
694	        LocalDate.of(2026, 12, 25),
695	        LocalDate.of(2026, 12, 28));
696	
697	    /**
698	     * A business day is any date that is neither a weekend day nor a listed public holiday.
699	     */
700	    private static boolean isBusinessDay(LocalDate date) {
701	        DayOfWeek day = date.getDayOfWeek();
702	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
703	    }
704	
705	    protected Set<Pet> getPetsInternal() {
706	        if (this.pets == null) {
707	            this.pets = new HashSet<>();
708	        }
709	        return this.pets;
710	    }
711	
712	    protected void setPetsInternal(Set<Pet> pets) {
713	        this.pets = pets;
714	    }
715	
716	    public List<Pet> getPets() {
717	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
718	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
719	        return Collections.unmodifiableList(sortedPets);
720	    }
721	
722	    public void setPets(List<Pet> pets) {
723	        this.pets = new HashSet<>(pets);
724	    }
725	
726	    public void addPet(Pet pet) {
727	        getPetsInternal().add(pet);
728	        pet.setOwner(this);
729	    }
730	
731	    /**
732	     * Return the Pet with the given name, or null if none found for this Owner.
733	     *
734	     * @param name to test
735	     * @return true if pet name is already in use
736	     */
737	    public Pet getPet(String name) {
738	        return getPet(name, false);
739	    }
740	
741	    /**
742	     * Return the Pet with the given name, or null if none found for this Owner.
743	     *
744	     * @param name to test
745	     * @return true if pet name is already in use
746	     */
747	    public Pet getPet(String name, boolean ignoreNew) {
748	        name = name.toLowerCase();
749	        for (Pet pet : getPetsInternal()) {
750	            if (!ignoreNew || !pet.isNew()) {
751	                String compName = pet.getName();
752	                compName = compName.toLowerCase();
753	                if (compName.equals(name)) {
754	                    return pet;
755	                }
756	            }
757	        }
758	        return null;
759	    }
760	
761	    public Pet getPet(Integer petId) {
762	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
763	    }
764	
765	    @Override
766	    public String toString() {
767	        return new ToStringCreator(this)
768	
769	            .append("id", this.getId())
770	            .append("new", this.isNew())
771	            .append("lastName", this.getLastName())
772	            .append("firstName", this.getFirstName())
773	            .append("address", this.address)
774	            .append("city", this.city)
775	            .append("telephone", this.telephone)
776	            .toString();
777	    }
778	}
